SECTIONS = []


def section(chapter, title, paragraphs, table=None, equations=None, figure=None, code=None):
    SECTIONS.append(dict(chapter=chapter, title=title, paragraphs=paragraphs,
                         table=table, equations=equations, figure=figure, code=code))


section("1 Giới thiệu đề tài", "1.1 Bài toán và mục tiêu", [
    "Khi một tệp được chuyển từ người gửi sang người nhận, nội dung có thể thay đổi do lỗi thao tác hoặc do can thiệp có chủ đích. Người nhận cần một cách kiểm tra rằng các byte đang nhận tương ứng với dữ liệu người gửi đã ký. Nếu chỉ gửi kèm một giá trị băm không được bảo vệ, bên sửa tệp có thể tính lại giá trị băm. Chữ ký số bổ sung một thao tác chỉ người giữ khóa bí mật mới thực hiện được, trong khi việc xác minh có thể công khai.",
    "Đề tài nghiên cứu mật mã đường cong elliptic, tập trung vào ECDSA để tạo và xác minh chữ ký số. Hai hàm SHA-256 và SHA-512 được dùng để tính đại diện của thông điệp. RSA-PSS được triển khai làm đối tượng so sánh. Ba lớp khái niệm được phân biệt: cấu trúc toán học ECC, lược đồ chữ ký ECDSA hoặc RSA-PSS và hàm băm SHA-2. Phân biệt này giúp giải thích đúng vai trò của từng bước thay vì gọi chung mọi thao tác là mã hóa.",
    "Mục tiêu thực hành là xây dựng một chương trình có giao diện tiếng Việt, cho phép tạo khóa, ký văn bản hoặc tệp, lưu chữ ký và xác minh độc lập bằng khóa công khai. Chương trình cũng cần làm rõ hậu quả của việc sửa dữ liệu: chữ ký hợp lệ đối với thông điệp ban đầu phải không còn hợp lệ đối với thông điệp mới. Những lỗi như nhập sai định dạng khóa hoặc sai mật khẩu cần được phân biệt với một chữ ký có định dạng đúng nhưng không xác minh được.",
    "Mục tiêu đánh giá là đo kích thước khóa công khai, kích thước chữ ký và thời gian của từng thao tác. So sánh sử dụng P-256 và RSA-3072, tương ứng mức an toàn cổ điển xấp xỉ 128 bit theo hướng dẫn quản lý khóa của NIST [4]. Kết quả sẽ được diễn giải trong phạm vi máy và phiên bản thư viện đã đo, thay vì xem một lần chạy là bằng chứng cho mọi nền tảng."
], table=(["Câu hỏi nghiên cứu", "Bằng chứng trong sản phẩm"], [
    ["Dữ liệu bị sửa có được phát hiện?", "Kiểm thử đổi byte và xác minh lại"],
    ["SHA-256 khác SHA-512 thế nào?", "Digest, độ dài, thời gian băm"],
    ["ECC so với RSA ra sao?", "Phép đo trên bốn cấu hình thống nhất"],
    ["Có tái lập được kết quả?", "Mã nguồn, CSV, metadata và kiểm thử"]]))

section("1 Giới thiệu đề tài", "1.2 Phạm vi và phương pháp", [
    "Sản phẩm chạy trên localhost bằng Python và Streamlit. Người dùng làm việc với văn bản UTF-8 hoặc tệp không quá 10 MiB. Chữ ký được lưu tách rời khỏi dữ liệu: để xác minh cần đồng thời tệp gốc, chữ ký JSON và khóa công khai PEM. Một tệp PDF có thể là dữ liệu đầu vào, nhưng chương trình không tạo chữ ký nhúng mà phần mềm đọc PDF tự nhận diện. Cách tổ chức này giữ trọng tâm ở thuật toán và tính toàn vẹn của byte.",
    "Phần ứng dụng sử dụng thư viện cryptography và OpenSSL cho sinh khóa, số ngẫu nhiên, băm và các phép ký. Việc tự cài đặt số học đường cong chỉ xuất hiện trong ví dụ trường nhỏ để kiểm tra phép tính trong báo cáo. Mô-đun minh họa không được giao diện nhập vào luồng ký thực tế. Nhờ tách biệt hai mục đích, người đọc vừa có thể theo dõi toán học vừa có thể đối chiếu ứng dụng với một thư viện có tài liệu rõ ràng.",
    "Phương pháp nghiên cứu gồm đọc tiêu chuẩn, mô hình hóa quy trình, xây dựng các hàm dùng chung, kiểm thử trường hợp hợp lệ và sai lệch, sau đó đo hiệu năng. Chương trình kiểm thử gọi đường xác minh trực tiếp trên thông điệp để kiểm tra đường ký digest. Đây là cách phát hiện nhầm lẫn băm hai lần mà một cặp hàm ký và xác minh cùng mắc lỗi có thể không bộc lộ qua kiểm thử vòng kín.",
    "Các yếu tố như chứng thư số, cấp phát danh tính, dấu thời gian tin cậy, thu hồi khóa và thiết bị HSM chưa thuộc phạm vi triển khai. Kết quả xác minh chỉ phát biểu mối quan hệ giữa thông điệp, chữ ký và khóa công khai được cung cấp. Báo cáo trình bày điều kiện để gắn kết quả đó với danh tính thực, nhưng không khẳng định demo đã đáp ứng một hệ thống chứng thực hay một quy trình ký số có giá trị pháp lý.",
    "Các chương tiếp theo đi từ số học trường hữu hạn đến ECDSA và SHA, rồi chuyển sang thiết kế và số liệu thực nghiệm. Mọi số liệu thực nghiệm có tệp nguồn để đối chiếu. Không sử dụng thời gian giả lập nhằm làm đẹp biểu đồ; điều kiện đo và giới hạn khái quát hóa được đặt cạnh phần phân tích."
])

section("2 Cơ sở toán học và ECC", "2.1 Số học modulo và trường hữu hạn", [
    "Số học modulo p làm việc với các lớp đồng dư, thường biểu diễn bằng các số từ 0 đến p − 1. Hai số nguyên a và b đồng dư modulo p khi hiệu a − b chia hết cho p. Phép cộng, trừ và nhân được thực hiện trên số nguyên rồi lấy phần dư. Khi p là số nguyên tố, mọi phần tử khác 0 có nghịch đảo nhân; tập hợp này cùng các phép toán tạo thành trường hữu hạn Fp.",
    "Nghịch đảo của a là số a⁻¹ thỏa a × a⁻¹ ≡ 1 (mod p). Ký hiệu phép chia trong các công thức đường cong phải được hiểu là nhân với nghịch đảo modulo, không phải phép chia số thực. Ví dụ trên F17, nghịch đảo của 2 là 9 vì 2 × 9 = 18 ≡ 1. Do đó 9/2 theo nghĩa trường hữu hạn bằng 9 × 9 ≡ 13, không phải 4,5.",
    "Thuật toán Euclid mở rộng tìm các số x và y sao cho ax + py = gcd(a,p). Nếu gcd bằng 1 thì x modulo p là nghịch đảo cần tìm. Định lý Fermat nhỏ cung cấp một cách khác: a^(p−2) modulo p bằng a⁻¹ đối với a khác 0. Trong phần minh họa, Python hỗ trợ pow(a, −1, p), giúp diễn đạt trực tiếp ý nghĩa này; phần ứng dụng thật giao cho thư viện xử lý.",
    "Trong ECDSA tồn tại hai modulo khác nhau. Tọa độ điểm và hệ số đường cong được tính modulo p, còn khóa bí mật, nonce, r, s và nghịch đảo khi ký được tính modulo n, với n là bậc của điểm sinh. Nhầm p và n là một lỗi cài đặt nghiêm trọng vì kết quả vẫn có thể trông như các số hợp lệ nhưng không tuân theo phép toán nhóm cần thiết."
], table=(["Phép tính trên F17", "Kết quả", "Giải thích"], [
    ["15 + 5", "3", "20 chia 17 dư 3"], ["3 − 7", "13", "−4 đồng dư 13"],
    ["5 × 8", "6", "40 chia 17 dư 6"], ["2⁻¹", "9", "2 × 9 ≡ 1"], ["9 / 2", "13", "9 × 9 ≡ 13"]]))

section("2 Cơ sở toán học và ECC", "2.2 Đường cong trên trường nguyên tố", [
    "Một dạng thường dùng của đường cong elliptic trên trường nguyên tố có đặc số lớn hơn 3 là y² = x³ + ax + b (mod p). Tập điểm gồm các cặp tọa độ thỏa phương trình và một điểm đặc biệt gọi là điểm vô cực O. Để đường cong không suy biến, cần 4a³ + 27b² khác 0 modulo p. Điều kiện này giúp cấu trúc phép cộng điểm có tính chất nhóm phù hợp.",
    "Hình đường cong liên tục trên số thực thường được dùng để giải thích trực quan phép cộng, nhưng dữ liệu của ECC trong đề tài nằm trên trường hữu hạn. Hình ảnh tương ứng là một tập hữu hạn các điểm rời rạc, không phải một đường vẽ trơn. Mọi kiểm tra điểm nằm trên đường cong đều là kiểm tra một phương trình đồng dư.",
    "Ví dụ xuyên suốt dùng p = 17, a = 2, b = 2. Điểm G = (5,1) thuộc đường cong vì 1² ≡ 5³ + 2×5 + 2 ≡ 1 modulo 17. Giá trị 4×2³ + 27×2² = 140 có phần dư 4 nên đường cong không suy biến. Đây là tham số rất nhỏ, chỉ phục vụ tính tay; việc dò toàn bộ khóa có thể thực hiện ngay nên không dùng để bảo vệ dữ liệu.",
    "Với một điểm P = (x,y), điểm đối là −P = (x,−y mod p). Hai điểm này có cùng tọa độ x. Trong ví dụ, điểm đối của (5,1) là (5,16). Điểm vô cực làm phần tử đơn vị: P + O = P. Phép cộng P + (−P) cho O. Nhận diện những trường hợp đặc biệt này quan trọng hơn việc áp dụng máy móc một công thức có mẫu số bằng 0. [1], [3]"
], equations=["E(Fp) = {(x,y) ∈ Fp² : y² ≡ x³ + ax + b (mod p)} ∪ {O}",
               "4a³ + 27b² ≢ 0 (mod p)"], figure="toy_curve.png")

section("2 Cơ sở toán học và ECC", "2.3 Cộng điểm và nhân đôi điểm", [
    "Xét hai điểm P = (x₁,y₁) và Q = (x₂,y₂) khác nhau, không phải hai điểm đối. Hệ số λ được tính bằng (y₂ − y₁)/(x₂ − x₁) trong trường Fp. Tọa độ điểm tổng R được suy ra từ λ. Trên số thực có thể hiểu đây là giao điểm thứ ba của đường thẳng với đường cong rồi lấy đối; trên trường hữu hạn ta dùng trực tiếp công thức đồng dư.",
    "Khi P = Q và y₁ khác 0, phép cộng trở thành nhân đôi. Hệ số λ khi đó là (3x₁² + a)/(2y₁). Các công thức tính x₃ và y₃ vẫn giống phép cộng. Nếu y₁ = 0 thì P là điểm đối của chính nó và 2P = O. Trong chương trình minh họa, kiểm tra hai điểm đối được thực hiện trước khi tính nghịch đảo để tránh mẫu số không khả nghịch.",
    "Tính 2G với G = (5,1) trên đường cong ví dụ: 3×5² + 2 = 77 ≡ 9; 2×1 = 2 có nghịch đảo 9; vậy λ ≡ 9×9 ≡ 13. Tọa độ x₃ ≡ 13² − 5 − 5 ≡ 6 và y₃ ≡ 13×(5−6) − 1 ≡ 3. Kết quả 2G = (6,3) tiếp tục thỏa phương trình đường cong.",
    "Để tính 3G, cộng (6,3) với (5,1). Hệ số λ = (3−1)/(6−5) ≡ 2, cho x₃ ≡ 4−6−5 ≡ 10 và y₃ ≡ 2×(5−10)−1 ≡ 6. Do đó 3G = (10,6). Các kết quả này được kiểm thử tự động, dùng làm điểm nối giữa công thức trong báo cáo và mã nguồn minh họa."
], equations=["λ = (y₂ − y₁)(x₂ − x₁)⁻¹ mod p",
               "λ = (3x₁² + a)(2y₁)⁻¹ mod p  khi P = Q",
               "x₃ = λ² − x₁ − x₂ mod p",
               "y₃ = λ(x₁ − x₃) − y₁ mod p"])

section("2 Cơ sở toán học và ECC", "2.4 Nhân vô hướng và nhóm sinh", [
    "Nhân vô hướng kP là cộng điểm P với chính nó k lần, không phải nhân riêng từng tọa độ với k. Cách lặp tuyến tính cần gần k phép cộng nên không phù hợp với số k lớn. Thuật toán nhân đôi và cộng khai thác biểu diễn nhị phân của k, giảm số bước xuống cùng bậc với số bit của k. Ví dụ 13P = 8P + 4P + P; các điểm 2P, 4P, 8P được tạo bằng nhân đôi.",
    "Mã giả dưới đây là phiên bản đơn giản để hiểu thuật toán. Nó không phải triển khai có thời gian hằng vì nhánh điều kiện phụ thuộc từng bit của k. Nếu dùng trực tiếp cho khóa bí mật, thời gian hoặc mẫu truy cập bộ nhớ có thể tiết lộ thông tin. Phần ký thực tế vì vậy không gọi thuật toán minh họa, mà sử dụng triển khai của thư viện chuyên dụng.",
    "Bậc n của điểm G là số nguyên dương nhỏ nhất sao cho nG = O. Các điểm O, G, 2G, …, (n−1)G tạo thành nhóm con sinh bởi G. Trên đường cong nhỏ đã chọn, G có bậc 19. Với khóa bí mật d = 7, khóa công khai Q = dG = (0,6). Trong nhóm này, 20G = G vì 20 đồng dư 1 modulo 19.",
    "Đặc tính phân phối k(P+Q) = kP+kQ và (a+b)G = aG+bG là cơ sở để chứng minh phép xác minh ECDSA. Khi các vô hướng được tính modulo n, hai vô hướng đồng dư tạo cùng một điểm trong nhóm sinh bởi G. Điều này giải thích tại sao phần ký làm việc modulo n trong khi tọa độ vẫn được tính modulo p."
], code="R ← O\nT ← P\nwhile k > 0:\n    if k lẻ: R ← R + T\n    T ← T + T\n    k ← floor(k / 2)\nreturn R",
table=(["k", "kG", "Ý nghĩa"], [["0", "O", "Phần tử đơn vị"], ["1", "(5,1)", "Điểm sinh"], ["2", "(6,3)", "Nhân đôi"], ["3", "(10,6)", "Dùng trong ví dụ ký"], ["7", "(0,6)", "Khóa công khai ví dụ"], ["19", "O", "Bậc của G"]]))

section("2 Cơ sở toán học và ECC", "2.5 Bài toán logarit rời rạc elliptic", [
    "Cho điểm sinh G và điểm Q = dG, bài toán logarit rời rạc elliptic yêu cầu tìm d. Tính Q từ d bằng nhân vô hướng tương đối hiệu quả, trong khi tìm ngược d trên nhóm được chọn phù hợp không có thuật toán cổ điển tổng quát hiệu quả tương đương. Sự bất đối xứng về chi phí này là cơ sở để công khai Q mà vẫn giữ d bí mật.",
    "Trên nhóm nhỏ bậc 19, chỉ cần tính lần lượt G, 2G, … để tìm khóa. Vì thế ví dụ toán học không chứng minh độ an toàn; nó chỉ chứng minh tính đúng của công thức. Các thuật toán tổng quát như Pollard rho có chi phí xấp xỉ căn bậc hai kích thước nhóm. Với nhóm bậc gần 2²⁵⁶, cách ước lượng phổ biến cho an toàn cổ điển là khoảng 128 bit, không phải 256 bit. [4]",
    "Không phải mọi đường cong đều an toàn chỉ vì p lớn. Cần xem xét cấu trúc nhóm, bậc nhóm con, hệ số đồng dư và các lớp đường cong có tính chất đặc biệt. Các bộ tham số chuẩn giúp tránh việc tự chọn đường cong thiếu căn cứ. Ứng dụng chỉ nhận SECP256R1 thay vì cho nhập a, b, p tùy ý. Việc kiểm tra loại khóa cũng làm cho các phép đo có cấu hình thống nhất.",
    "Mức an toàn toán học còn khác độ an toàn triển khai. Một chương trình có thể để lộ d qua log, xuất khóa không được bảo vệ, dùng nguồn ngẫu nhiên yếu hoặc mắc lỗi kênh kề mà không cần giải ECDLP. Trong demo, khóa bí mật nằm trong trạng thái phiên; khi xuất cần mật khẩu và định dạng mã hóa của thư viện. Cách làm này giảm lỗi sử dụng thông thường nhưng chưa thay thế kho khóa chuyên dụng hay HSM.",
    "Báo cáo sử dụng thuật ngữ an toàn cổ điển để nêu rõ mô hình tấn công. ECC và RSA hiện hành không phải thuật toán chữ ký hậu lượng tử. Nhận xét này xác định giới hạn của họ thuật toán, không phải kết quả của phép đo tốc độ trong sản phẩm."
])

section("2 Cơ sở toán học và ECC", "2.6 Tham số P256 và vòng đời khóa", [
    "P-256 là một đường cong chuẩn trên trường nguyên tố, được thư viện gọi là SECP256R1. Bộ tham số bao gồm p, a, b, tọa độ điểm sinh G, bậc n và hệ số h. Chương trình tạo khóa thông qua ec.generate_private_key(ec.SECP256R1()), để thư viện chọn d trong miền hợp lệ và tính Q = dG. Việc ghi lại tên đường cong giúp người nhận biết cách diễn giải khóa công khai. [3], [6]",
    "Khóa công khai được xuất theo SubjectPublicKeyInfo ở dạng PEM. PEM là cách biểu diễn văn bản của dữ liệu nhị phân và có phần tiêu đề, kết thúc. Vì Base64 và các dòng tiêu đề tạo thêm byte, không nên dùng độ dài tệp PEM để suy ra độ dài khóa toán học. Trong so sánh dung lượng, đề tài dùng cùng kiểu SPKI DER cho khóa công khai và byte chữ ký trước Base64.",
    "Fingerprint trong giao diện là SHA-256 của SPKI DER. Hai bên có thể đối chiếu chuỗi này qua một kênh đáng tin để phát hiện việc nhận nhầm khóa. Tuy nhiên, một fingerprint hiển thị ngay cạnh khóa trên cùng kênh bị thay thế không tự chứng minh danh tính. Kẻ thay khóa có thể thay luôn fingerprint. Cần phân biệt công cụ đối chiếu với cơ chế phân phối khóa tin cậy.",
    "Khóa bí mật được xuất dưới dạng PKCS8 PEM có mã hóa, sử dụng BestAvailableEncryption và mật khẩu người dùng nhập. Khi nạp lại, chương trình yêu cầu đúng định dạng và mật khẩu. Nếu mất khóa bí mật thì không thể ký tiếp với danh tính khóa đó; tạo cặp khóa mới không làm cho các chữ ký cũ chuyển sang khóa mới. Khóa công khai cũ vẫn cần để xác minh các chữ ký đã tạo.",
    "Giao diện có nút xóa phiên để bỏ các tham chiếu tới khóa và kết quả trong bộ nhớ ứng dụng. Đây không phải bảo đảm xóa sạch mọi bản sao vật lý trong RAM vì Python quản lý bộ nhớ tự động. Đối với triển khai thực tế có yêu cầu cao, vòng đời khóa cần bổ sung quyền truy cập, sao lưu, thu hồi và phần cứng bảo vệ thích hợp."
])

section("2 Cơ sở toán học và ECC", "2.7 Ví dụ số ECDSA trên trường nhỏ", [
    "Dùng đường cong y² = x³ + 2x + 2 trên F17, điểm G = (5,1), bậc n = 19. Chọn khóa bí mật d = 7, suy ra Q = 7G = (0,6). Giả sử đại diện thông điệp sau bước xử lý hàm băm là z = 13. Giá trị z ở đây được chọn để tính tay; ví dụ không giả định SHA-256 tạo ra trực tiếp số 13.",
    "Chọn nonce k = 3. Khi đó R = 3G = (10,6), r = 10 mod 19 = 10. Nghịch đảo của 3 modulo 19 là 13. Tính s = 13×(13 + 10×7) mod 19 = 15. Chữ ký là cặp (10,15). Các giá trị r và s đều nằm trong khoảng 1 đến 18 nên không rơi vào trường hợp cần chọn lại nonce.",
    "Bên xác minh tính w = 15⁻¹ mod 19 = 14, u₁ = 13×14 mod 19 = 11 và u₂ = 10×14 mod 19 = 7. Điểm X = 11G + 7Q = 11G + 49G = 60G = 3G = (10,6). Giá trị xX mod 19 bằng 10, trùng r, vì vậy chữ ký hợp lệ.",
    "Để thấy ảnh hưởng của thông điệp, giữ nguyên chữ ký nhưng thay z bằng 12. Khi đó u₁ = 16, u₂ vẫn là 7, nên X = (16 + 49)G = 65G = 8G = (13,7). Giá trị 13 không bằng r = 10, vì vậy phép xác minh thất bại. Kiểm tra này cho thấy thông điệp tham gia trực tiếp vào điều kiện chấp nhận.",
    "Các phép tính được đặt trong mô-đun toy_curve.py và kiểm thử bằng giá trị kỳ vọng cụ thể. Không tái sử dụng khóa hoặc nonce từ ví dụ cho P-256. Đường cong nhỏ cho phép liệt kê toàn bộ không gian khóa và do đó không có giá trị bảo mật."
], table=(["Đại lượng", "Giá trị", "Modulo"], [["d, k, z", "7, 3, 13", "19"], ["Q", "(0,6)", "Tọa độ mod 17"], ["R", "(10,6)", "Tọa độ mod 17"], ["r, s", "10, 15", "19"], ["w, u₁, u₂", "14, 11, 7", "19"], ["X", "(10,6)", "xX mod 19 = r"]]))

section("3 Hàm băm và chữ ký số", "3.1 Vai trò và thuộc tính của hàm băm", [
    "Hàm băm nhận một chuỗi byte độ dài biến đổi và tạo digest có độ dài cố định. Trong đề tài, SHA-256 cho 256 bit và SHA-512 cho 512 bit. Chuyển digest sang chuỗi hex không thay đổi thông tin: mỗi byte được biểu diễn bằng hai ký tự hex. Vì vậy giao diện hiển thị SHA-256 bằng 64 ký tự, SHA-512 bằng 128 ký tự. [2]",
    "Ba thuộc tính thường được phân biệt là chống tiền ảnh, chống tiền ảnh thứ hai và chống va chạm. Chống tiền ảnh liên quan việc tìm một thông điệp từ digest đã biết. Chống tiền ảnh thứ hai liên quan việc tìm thông điệp khác cùng digest với một thông điệp cho trước. Chống va chạm liên quan việc tìm bất kỳ hai thông điệp khác nhau có cùng digest. Ba bài toán không có cùng điều kiện đầu vào hay cùng chi phí tổng quát.",
    "Với một hàm băm lý tưởng có đầu ra b bit, tìm va chạm bằng phương pháp sinh nhật có quy mô khoảng 2^(b/2), trong khi tìm tiền ảnh tổng quát có quy mô khoảng 2^b. Các con số này là mô hình lý tưởng để hiểu ý nghĩa độ dài đầu ra, không phải phép đo thực tế của chương trình. Màn hình so sánh số bit thay đổi chỉ minh họa khuếch tán, không chứng minh các thuộc tính an toàn trên.",
    "Trong chữ ký số, digest giúp quy trình xử lý thông điệp dài theo giao diện ổn định. Toàn bộ dữ liệu vẫn phải được đọc và băm; ký tệp lớn không có nghĩa bỏ qua phần lớn dữ liệu. Bên xác minh phải tính lại digest từ byte thật, không chỉ tin digest được người gửi ghi trong metadata. Nếu thay dữ liệu nhưng giữ digest cũ mà không tính lại, hệ thống sẽ không kiểm tra được tính toàn vẹn như mục tiêu đề tài.",
    "Một giá trị băm công khai không phải chữ ký. Ai cũng có thể băm một thông điệp mới. Tính ràng buộc với khóa bí mật đến từ ECDSA hoặc RSA-PSS. Ngược lại, chữ ký không mã hóa nội dung: người có tệp vẫn đọc được tệp ngay cả khi chưa có khóa xác minh."
])

section("3 Hàm băm và chữ ký số", "3.2 Cấu trúc SHA256 và SHA512", [
    "SHA-256 và SHA-512 cùng thuộc họ SHA-2, xử lý dữ liệu theo khối và cập nhật một trạng thái bên trong. Trước khi xử lý, thông điệp được thêm bit 1, các bit 0 và thông tin độ dài để tổng dữ liệu phù hợp với cấu trúc khối. Thông tin độ dài được tính theo bit. Kết quả cuối cùng được ghép từ các từ trạng thái theo thứ tự quy định. [2]",
    "SHA-256 làm việc với từ 32 bit và khối 512 bit; SHA-512 làm việc với từ 64 bit và khối 1024 bit. Mỗi khối được mở rộng thành lịch từ rồi đi qua nhiều vòng cập nhật trạng thái. Các phép toán gồm cộng modulo 2^w, XOR, AND, NOT, dịch và quay bit. Các phép cộng trong SHA khác với số học modulo p/n của ECC; chúng thuộc một lớp thuật toán khác.",
    "Các hàm Ch và Maj thể hiện lựa chọn bit và lấy đa số bit. Các hàm sigma sử dụng tổ hợp phép quay và dịch để trộn thông tin. Số vòng, hằng số và lượng dịch cụ thể của SHA-256 và SHA-512 khác nhau. Báo cáo không tự viết lại SHA để dùng trong ứng dụng; cách kiểm tra triển khai là đối chiếu digest đã biết và sử dụng giao diện của thư viện.",
    "Không thể suy ra SHA-512 luôn chậm gấp đôi SHA-256 chỉ từ độ dài digest. Hiệu năng phụ thuộc CPU, tập lệnh tăng tốc, cách tối ưu của OpenSSL, độ dài thông điệp và chi phí gọi hàm. Vì vậy chương trình đo hai hàm trên cùng bộ byte và tách phép băm khỏi chữ ký. Với thông điệp ngắn, chi phí tạo đối tượng và gọi Python có thể chiếm tỷ trọng đáng kể."
], table=(["Thuộc tính", "SHA-256", "SHA-512"], [["Đầu ra", "256 bit", "512 bit"], ["Từ xử lý", "32 bit", "64 bit"], ["Khối đầu vào", "512 bit", "1024 bit"], ["Số vòng/khối", "64", "80"], ["Trường ghi độ dài", "64 bit", "128 bit"], ["Digest dạng hex", "64 ký tự", "128 ký tự"]]), equations=["Ch(x,y,z) = (x AND y) XOR ((NOT x) AND z)", "Maj(x,y,z) = (x AND y) XOR (x AND z) XOR (y AND z)"])

section("3 Hàm băm và chữ ký số", "3.3 Tạo chữ ký ECDSA", [
    "Đầu vào gồm thông điệp M, khóa bí mật d và tham số miền của đường cong. Tính H(M), sau đó chuyển digest thành số nguyên z theo quy tắc ECDSA. Khi digest dài hơn số bit cần thiết của bậc n, sử dụng phần bit bên trái phù hợp. Với P-256 và SHA-512, không được hiểu rằng toàn bộ 512 bit trở thành một mức an toàn mới cho đường cong. Thư viện chịu trách nhiệm bước chuyển đổi này. [1], [6]",
    "Mỗi lần ký cần một nonce k hợp lệ trong khoảng 1 đến n−1. Tính điểm R = kG và r = xR mod n. Nếu r = 0, cần sinh lại k. Sau đó s = k⁻¹(z + rd) mod n; nếu s = 0 cũng cần lặp lại. Kết quả là cặp (r,s). Trong demo, chữ ký được thư viện mã hóa ASN.1 DER rồi chuyển Base64 để đặt vào JSON.",
    "Nonce phải được quản lý đúng. Nếu cùng k bị dùng cho hai thông điệp khác nhau trong ECDSA ngẫu nhiên, hai phương trình chữ ký có thể làm lộ k rồi lộ khóa bí mật d. Nguồn ngẫu nhiên yếu hoặc việc tự cố định k để làm demo là lỗi nguy hiểm. Vì thế chương trình không cho người dùng nhập nonce; tham số k cố định chỉ tồn tại trong ví dụ số nhỏ không bảo mật.",
    "Ứng dụng tính digest trước để hiển thị và đo riêng. Hàm ký dùng ec.ECDSA(utils.Prehashed(hash_algorithm)). Nếu đưa digest vào một API vốn mặc định tự băm thông điệp mà không khai báo Prehashed, chữ ký sẽ ràng buộc với H(H(M)) thay cho cách kết hợp dự kiến. Việc dùng cùng sai lầm ở cả phía ký và xác minh có thể che giấu lỗi, nên kiểm thử có thêm đường xác minh độc lập trên byte gốc."
], equations=["Q = dG", "R = kG;  r = xR mod n", "s = k⁻¹(z + rd) mod n", "Chữ ký = (r,s),  1 ≤ r,s ≤ n−1"], code="digest ← SHA(M)\nsignature ← private_key.sign(digest, ECDSA(Prehashed(SHA)))\nJSON ← thuật toán + hàm băm + Base64(signature)")

section("3 Hàm băm và chữ ký số", "3.4 Xác minh ECDSA và tính đúng", [
    "Người xác minh cần thông điệp, chữ ký (r,s), khóa công khai Q và bộ tham số tương ứng. Trước hết cần xác nhận chữ ký có định dạng hợp lệ và r,s nằm trong khoảng 1 đến n−1. Khóa công khai phải thuộc loại đường cong mà ứng dụng hỗ trợ. Thư viện giải mã khóa, kiểm tra điểm và thực hiện phép xác minh; ứng dụng bổ sung kiểm tra cấu hình P-256.",
    "Sau khi tính lại z từ thông điệp, bên xác minh tính w = s⁻¹ mod n, u₁ = zw mod n và u₂ = rw mod n. Tiếp theo tính X = u₁G + u₂Q. Nếu X = O thì từ chối. Nếu khác O, chấp nhận khi xX mod n bằng r. Thông điệp chỉ được xác nhận khi toàn bộ điều kiện của phép xác minh đều đạt. [1]",
    "Tính đúng có thể thấy bằng thay Q = dG: X = (z + rd)s⁻¹G. Vì s = k⁻¹(z+rd) modulo n, suy ra X = kG trong nhóm sinh bởi G. Điểm X do bên xác minh dựng lại vì vậy có cùng tọa độ x cần dùng với R của bên ký. Đây là lý do chữ ký hợp lệ xác minh được mà người nhận không cần biết d hay k.",
    "Điều kiện toán học không tự giải quyết việc phân phối khóa. Nếu người nhận lấy một khóa công khai do kẻ giả mạo cung cấp và kẻ đó ký bằng khóa bí mật tương ứng, chữ ký có thể hợp lệ về toán học nhưng không chứng minh người ký là người được mong đợi. Giao diện vì vậy nêu rõ kết quả hợp lệ với khóa được cung cấp và hiển thị fingerprint để đối chiếu.",
    "Ứng dụng trả về hai loại kết quả khác nhau: lỗi đọc/định dạng và kết quả mật mã không hợp lệ. Một chữ ký DER bị hỏng có thể bị từ chối ở lớp định dạng trước khi kiểm tra toán học. Một chữ ký có định dạng đúng nhưng thuộc tệp khác sẽ đi đến phép xác minh và trả về thất bại. Cả hai đều không được hiển thị là thành công."
], equations=["w = s⁻¹ mod n", "u₁ = zw mod n;  u₂ = rw mod n", "X = u₁G + u₂Q = (z + rd)s⁻¹G = kG", "Chấp nhận khi X ≠ O và xX mod n = r"])

section("3 Hàm băm và chữ ký số", "3.5 RSA và cơ chế RSAPSS", [
    "RSA sử dụng modulus N = pq từ hai số nguyên tố lớn p và q. Khóa công khai gồm N và e; khóa bí mật chứa d cùng các thành phần giúp thực hiện phép toán hiệu quả. Quan hệ ed ≡ 1 modulo λ(N) tạo cơ sở cho việc đảo phép lũy thừa trong miền thích hợp. Ứng dụng dùng e = 65537 và modulus dài 3072 bit để có cấu hình cố định. [5]",
    "Không nên mô tả chữ ký RSA-PSS đơn giản là mã hóa bằng khóa bí mật. Trước phép toán RSA, PSS mã hóa digest theo một cấu trúc có salt và hàm tạo mặt nạ MGF1. Cấu trúc này ràng buộc thông điệp và tham số theo lược đồ chữ ký. Bên xác minh thực hiện phép toán công khai rồi kiểm tra cấu trúc mã hóa, thay vì giải mã ra nguyên thông điệp như một lược đồ mã hóa.",
    "Trong sản phẩm, MGF1 dùng cùng SHA-256 hoặc SHA-512 với hàm băm thông điệp. Salt dài bằng digest, tương ứng 32 hoặc 64 byte. Hai phía ký và xác minh phải thống nhất các tham số này; nếu chỉ biết RSA và SHA mà bỏ qua PSS, độ dài salt hoặc MGF1, không đủ để định nghĩa thao tác xác minh của ứng dụng.",
    "Chữ ký RSA-3072 có độ dài 3072/8 = 384 byte. Kích thước này không thay đổi khi thay SHA-256 bằng SHA-512 trong cấu hình đã chọn. ECDSA mã hóa cặp số nguyên bằng DER nên có thể thay đổi một vài byte giữa các lần ký; do đó bảng so sánh báo cáo khoảng min/max của chữ ký ECDSA và không nhầm DER với biểu diễn r||s cố định.",
    "Phép xác minh RSA với số mũ công khai nhỏ thường có đặc tính chi phí khác phép ký bằng khóa bí mật. Cài đặt RSA còn có thể dùng định lý phần dư Trung Hoa để tăng tốc phía bí mật. Vì vậy phải đo ký và xác minh riêng; một kết luận chỉ dựa trên thời gian ký sẽ bỏ qua nhu cầu hệ thống có rất nhiều lượt xác minh."
], equations=["N = p × q", "ed ≡ 1 (mod λ(N))", "sig = RSASP1(private_key, EMSA-PSS-ENCODE(M))"], table=(["Tham số PSS", "Giá trị trong demo"], [["Modulus / e", "3072 bit / 65537"], ["MGF", "MGF1 với cùng SHA"], ["Salt", "32 byte hoặc 64 byte"], ["Độ dài chữ ký", "384 byte trước Base64"]]))

section("3 Hàm băm và chữ ký số", "3.6 So sánh theo mức an toàn tương đương", [
    "Số bit của khóa không trực tiếp là số bit an toàn. RSA và ECC dựa trên các bài toán toán học khác nhau, với các thuật toán tấn công cổ điển đã biết khác nhau. Đề tài dùng mốc 128 bit: RSA với modulus 3072 bit và ECC với bậc nhóm có độ dài thuộc khoảng phù hợp, ở đây là P-256. Hướng dẫn NIST cung cấp cơ sở cho cách ghép này. [4]",
    "So sánh dung lượng có ba đại lượng phải tách: độ dài khóa toán học, kích thước bản mã hóa khóa công khai và kích thước chữ ký. SPKI DER chứa cả thông tin thuật toán và dữ liệu khóa, nên số byte không đơn giản bằng số bit khóa chia 8. Tương tự, PEM thêm Base64 và tiêu đề; JSON chữ ký thêm metadata. Chương trình đo byte ở định dạng được nêu rõ để người đọc có thể tái lập.",
    "So sánh tốc độ phải tách tạo khóa, băm, ký digest và xác minh digest. Tạo khóa thường là thao tác ít xảy ra hơn ký hoặc xác minh, nhưng có thể quan trọng với hệ thống tạo nhiều danh tính tạm thời. Thông điệp lớn làm tăng thời gian băm trong khi độ dài đầu vào của phép ký digest không tăng. Đó là lý do bảng thực nghiệm chứa cả thời gian thao tác mật mã riêng và thời gian băm cộng thao tác.",
    "Việc thay SHA-256 bằng SHA-512 khảo sát sự thay đổi trong lớp băm và cách kết hợp với chữ ký. Nó không làm cho P-256 trở thành một đường cong có mức an toàn 256 hay 512 bit. Mức an toàn hệ thống còn bị giới hạn bởi khóa, lược đồ, hàm băm, quản lý khóa và mô hình tấn công. Báo cáo vì vậy không xếp hạng cấu hình chỉ theo số trong tên SHA.",
    "Các tính chất ngoài hiệu năng cũng ảnh hưởng lựa chọn triển khai: hỗ trợ của thiết bị, định dạng trao đổi, yêu cầu chứng thực, khả năng bảo vệ khóa và thư viện sẵn có. Demo giữ hai cấu hình đơn giản để kiểm chứng nguyên lý, còn quyết định dùng trong hệ thống thật cần đánh giá toàn bộ bối cảnh."
], table=(["Tiêu chí", "ECDSA P-256", "RSA-PSS 3072"], [["Bài toán nền", "ECDLP", "Liên quan bài toán RSA và phân tích số"], ["An toàn cổ điển tham chiếu", "Khoảng 128 bit", "Khoảng 128 bit"], ["Chữ ký thực tế", "DER của r,s", "384 byte"], ["Ngẫu nhiên khi ký", "Nonce k", "Salt của PSS"], ["Đầu vào ứng dụng", "SHA-256 hoặc SHA-512", "SHA-256 hoặc SHA-512"]]))

section("3 Hàm băm và chữ ký số", "3.7 Các lỗi sử dụng cần kiểm soát", [
    "Lỗi thường gặp đầu tiên là khác byte dù người dùng thấy nội dung gần giống nhau. Một dấu xuống dòng CRLF khác LF, một khoảng trắng cuối dòng hoặc cách biểu diễn Unicode khác cũng tạo thông điệp khác. Ứng dụng không tự chuẩn hóa văn bản để tránh che giấu thay đổi. Với văn bản nhập trực tiếp, mã hóa UTF-8 được dùng nhất quán; với tệp tải lên, các byte được giữ nguyên.",
    "Lỗi thứ hai là xác minh trên thông tin do người gửi tự khai mà không kiểm tra dữ liệu thật. Chương trình không đọc một trường digest từ JSON rồi tin rằng đó là digest của tệp. Nó luôn băm lại nội dung hiện tại. Metadata chỉ định cách xác minh và bị giới hạn trong danh sách hỗ trợ; thay metadata không tạo ra một chữ ký mới hợp lệ cho dữ liệu bất kỳ.",
    "Lỗi thứ ba là trạng thái giao diện gây hiểu lầm. Sau khi xác minh thành công, nếu người dùng thay tệp nhưng màn hình vẫn giữ thông báo xanh, họ có thể tưởng dữ liệu mới đã được kiểm tra. Chương trình xóa kết quả khi đầu vào, hàm băm hoặc khóa đổi, đồng thời liên kết kết quả ký với fingerprint đầu vào và khóa. Kiểm thử giao diện kiểm tra việc xóa kết quả cũ này.",
    "Một lỗi khác là coi thành công của một vòng ký/xác minh là đủ. Nếu cả hai phía cùng băm hai lần hoặc dùng nhầm cấu hình, chúng vẫn có thể chấp nhận nhau. Bộ kiểm thử dùng vector SHA chuẩn và đường gọi thư viện trực tiếp trên thông điệp, bên cạnh kiểm thử tệp hỏng và sai khóa. Đây là kiểm tra tích hợp khác đường gọi, chưa phải chứng nhận bởi một tổ chức kiểm định.",
    "Cuối cùng, việc quản lý khóa và mô hình triển khai phải phù hợp. Demo chỉ bind 127.0.0.1, không mở dịch vụ công khai. Không đưa khóa bí mật vào Git, báo cáo hoặc bộ mẫu. Nếu triển khai cho nhiều người dùng, cần một thiết kế riêng về xác thực, cách ly phiên, quyền truy cập và bảo vệ khóa; không chỉ đổi địa chỉ bind của ứng dụng hiện tại."
])

section("4 Thiết kế và xây dựng ứng dụng", "4.1 Kiến trúc và luồng dữ liệu", [
    "Kiến trúc gồm lớp giao diện Streamlit, lớp dịch vụ mật mã và lớp thực nghiệm. Giao diện nhận dữ liệu và lựa chọn của người dùng rồi gọi các hàm trong crypto.py. Mô-đun benchmark.py dùng lại chính các hàm này để phép đo phản ánh mã của sản phẩm. Bộ kiểm thử gọi cả lớp dịch vụ và giao diện mô phỏng của Streamlit.",
    "Luồng ký bắt đầu từ byte thông điệp. Hàm digest tính SHA đã chọn, sign_digest tạo chữ ký và SignatureEnvelope đóng gói metadata cùng Base64. Luồng xác minh phân tích JSON, nạp khóa công khai, kiểm tra cấu hình, tính lại digest từ byte hiện tại rồi gọi verify_digest. Không có cơ sở dữ liệu hoặc máy chủ xử lý bên ngoài localhost.",
    "Mọi thao tác mật mã dài hơn một bước đều có đầu vào và đầu ra rõ ràng. Tạo khóa trả đối tượng khóa bí mật; đối tượng này cung cấp khóa công khai tương ứng. Ký trả chữ ký kèm cấu hình. Xác minh trả giá trị đúng/sai cho kết quả mật mã, còn lỗi định dạng được chuyển thành InputError có thông báo tiếng Việt. Cách tách này giúp giao diện không phải diễn giải lỗi tầng thấp của thư viện.",
    "Mô-đun toy_curve.py đứng riêng, chỉ dùng để kiểm tra ví dụ trường nhỏ trong báo cáo. Nó không được nhập vào crypto.py. Việc này tránh khả năng người đọc nhầm thuật toán nhân đôi/cộng đơn giản với phần cài đặt thực tế có yêu cầu nguồn ngẫu nhiên và kênh kề.",
    "Các tệp CSV và biểu đồ được sinh sau khi đo xong. Cập nhật thanh tiến độ cũng nằm ngoài khoảng đồng hồ của từng phép đo. Điều này giảm việc trộn chi phí giao diện với chi phí mật mã, dù không thể loại hết ảnh hưởng tiến trình nền hoặc hệ điều hành."
], figure="architecture.png")

section("4 Thiết kế và xây dựng ứng dụng", "4.2 Giao diện quản lý khóa và hàm băm", [
    "Khu vực Quản lý khóa cho phép chọn ECDSA hoặc RSA-PSS và tạo cặp khóa. Sau khi tạo, giao diện hiển thị thuật toán, số bit khóa, kích thước khóa công khai DER và fingerprint. Người dùng có thể tải PEM công khai để chuyển cho bên xác minh. Khóa bí mật chỉ được xuất khi có mật khẩu; giao diện không in các thành phần bí mật dưới dạng số.",
    "Nhập khóa dùng tệp PEM đã mã hóa và mật khẩu. Chương trình từ chối khóa EC không phải P-256, RSA không phải 3072 bit hoặc e khác 65537. Hạn chế này là cấu hình của thí nghiệm, không phải nhận định rằng mọi khóa ngoài phạm vi đều không an toàn. Nó giữ các phép đo và cách giải thích trong báo cáo thống nhất.",
    "Khu vực Khám phá SHA nhận văn bản hoặc tệp và hiển thị đồng thời SHA-256, SHA-512. Digest được thể hiện bằng hex, kèm số byte, số bit và số ký tự. Khi nhập nội dung mới để so sánh, chương trình tính khoảng cách Hamming giữa hai digest: đếm số bit khác nhau trong từng cặp byte.",
    "Tỷ lệ bit thay đổi giúp người học quan sát khuếch tán. Chương trình không đặt điều kiện phải đúng 50 phần trăm ở mọi lần thử, vì một cặp thông điệp cụ thể có thể lệch khỏi tỷ lệ đó. Nội dung giải thích ngay dưới kết quả nhắc rằng một minh họa không chứng minh tính chống va chạm. Khi chọn tệp nhưng chưa tải tệp lên, giao diện chờ đầu vào thay vì băm nhầm một giá trị không xác định."
], figure="ui_hash.png")

section("4 Thiết kế và xây dựng ứng dụng", "4.3 Giao diện ký và xác minh độc lập", [
    "Màn hình Ký và xác minh có hai tab, phân biệt rõ người tạo chữ ký và người kiểm tra. Nếu chưa có khóa, người dùng có thể tạo nhanh ECDSA P-256 hoặc vào Quản lý khóa để chọn thuật toán khác. Nút ký chỉ hoạt động khi có khóa và đầu vào hợp lệ. Thông điệp rỗng được xem là một chuỗi byte hợp lệ và vẫn có digest, khác với chưa chọn tệp.",
    "Sau khi ký, màn hình hiển thị độ dài chữ ký trước Base64 và giá trị băm. Người dùng tải riêng chữ ký JSON, dữ liệu đã ký và khóa công khai. Tải byte dữ liệu đã ký là cách tránh việc chép lại văn bản rồi vô tình thay khoảng trắng hoặc xuống dòng. Một nút kiểm tra nhanh xác minh ngay chữ ký hiện tại bằng khóa công khai tương ứng.",
    "Nút Sửa một byte đảo bit thấp nhất của byte đầu tiên. Nếu thông điệp rỗng, nó thêm một byte. Chữ ký vẫn giữ nguyên nên phép xác minh phải thất bại. Cách tạo thay đổi này xác định rõ điều gì đã bị sửa, thay vì chỉ hiển thị một thông báo giả lập. Đây là lời gọi thật tới cùng hàm verify của ứng dụng.",
    "Tab xác minh độc lập nhận dữ liệu, PEM công khai và JSON chữ ký. Nó không sử dụng khóa bí mật trong phiên để quyết định kết quả. Người dùng có thể mở phiên mới hoặc dùng bộ mẫu công khai để kiểm tra. Thông báo thành công diễn đạt rằng chữ ký hợp lệ với dữ liệu và khóa đã cung cấp, đồng thời cho biết thuật toán, hàm băm và fingerprint.",
    "Khi đầu vào thay đổi, kết quả trước đó được loại bỏ. Ngoài callback, chương trình còn kiểm tra ngữ cảnh ký gồm SHA-256 của dữ liệu, lựa chọn hàm băm và fingerprint khóa. Điều này xử lý cả trường hợp chuyển trang khiến widget được tạo lại với giá trị mặc định."
], figure="ui_signature.png")

section("4 Thiết kế và xây dựng ứng dụng", "4.4 Định dạng trao đổi và xử lý lỗi", [
    "Chữ ký tách rời dùng JSON phiên bản 1 với đúng năm trường. Trường algorithm nhận ECDSA hoặc RSA-PSS; hash nhận SHA-256 hoặc SHA-512; key_profile phải phù hợp với thuật toán. Trường signature_base64 chỉ chứa chữ ký nhị phân được mã hóa Base64. Phiên bản định dạng giúp chương trình từ chối một cấu trúc chưa được hỗ trợ thay vì tự suy đoán.",
    "Trình phân tích từ chối trường trùng lặp, trường thừa, phiên bản không đúng kiểu số nguyên và Base64 không hợp lệ. Giới hạn JSON 16 KiB đủ cho cấu hình này; tệp khóa giới hạn 64 KiB. Với ECDSA, cấu trúc DER được giải mã để kiểm tra cặp số nguyên nằm trong miền cho phép. Với RSA, chữ ký phải dài 384 byte. Các kiểm tra này diễn ra trước phép xác minh mật mã.",
    "JSON không chứa thời điểm ký hay tên người ký vì demo chưa có cơ chế chứng thực các thuộc tính đó. Tên tệp và đường dẫn không thuộc thông điệp được ký; thay tên tệp không đổi byte thì không làm mất hiệu lực chữ ký. Nếu một ứng dụng muốn ràng buộc cả metadata, nó cần định nghĩa thông điệp chuẩn hóa chứa metadata rồi ký thông điệp đó. Đây là một thiết kế khác với định dạng hiện tại.",
    "Mật khẩu sai hoặc PEM không đọc được được báo là lỗi đầu vào. Trường hợp khóa đúng định dạng nhưng không khớp chữ ký trả về không hợp lệ. Người dùng không nhìn thấy traceback của thư viện trong các tình huống dự kiến. Lỗi tài nguyên hoặc lỗi chương trình ngoài phạm vi đầu vào vẫn cần được chẩn đoán riêng, không nên chuyển mọi ngoại lệ thành một kết quả chữ ký sai."
], table=(["Trường", "Ví dụ ECDSA", "Ràng buộc"], [["version", "1", "Số nguyên đúng bằng 1"], ["algorithm", "ECDSA", "Danh sách hỗ trợ"], ["hash", "SHA-256", "SHA-256 / SHA-512"], ["key_profile", "P-256", "Phải khớp algorithm"], ["signature_base64", "Chữ ký DER mã hóa", "Base64 hợp lệ"]]))

section("4 Thiết kế và xây dựng ứng dụng", "4.5 Tổ chức triển khai và khả năng tái lập", [
    "Dự án sử dụng môi trường ảo để tách các gói phụ thuộc khỏi Python hệ thống. Tệp requirements.txt cố định phiên bản đã cài và kiểm thử. Phiên chạy thực tế dùng Python 3.13 trên Windows; bộ thư viện đã khóa yêu cầu Python từ 3.12. Các phiên bản chưa chạy không được xem là đã kiểm chứng. README cung cấp lệnh tạo môi trường, cài thư viện, mở giao diện và chạy kiểm thử.",
    "Cấu hình Streamlit bind 127.0.0.1 và đặt giới hạn upload 10 MiB. Bộ mẫu chỉ chứa thông điệp, thông điệp đã sửa, khóa công khai và chữ ký. Khóa bí mật sinh để tạo mẫu không được lưu. Người kiểm tra có thể xác minh các mẫu ngay mà không cần biết mật khẩu hoặc tạo một danh tính mới.",
    "Mô-đun thực nghiệm có giao diện dòng lệnh và được gọi lại từ màn hình Thực nghiệm. Chế độ đầy đủ dùng thông số của báo cáo; chế độ nhanh dành cho kiểm tra công cụ và được ghi rõ trong metadata. Chương trình không tự trộn dữ liệu hai chế độ. Kết quả tham chiếu được giữ trong thư mục riêng để lần chạy mới không ghi đè nguồn số liệu đã dùng.",
    "Nguồn nội dung báo cáo là tệp Python chứa các đoạn văn, bảng và tham chiếu hình. Trình dựng đọc CSV, metadata và kết quả kiểm thử để điền bảng thực nghiệm. Vì vậy khi chạy lại trên máy khác, cần tạo lại báo cáo từ lần đo mới thay vì sửa thủ công từng con số trong Word. Bản Word vẫn có thể chỉnh sửa để điền thông tin học phần và điều chỉnh theo mẫu của giảng viên.",
    "Quy trình bàn giao gồm kiểm tra môi trường, chạy kiểm thử, xác minh mẫu công khai, chạy phép đo đầy đủ, kiểm tra biểu đồ và tạo tài liệu. Kịch bản trình bày nêu các thao tác có thể thực hiện trong 5 đến 7 phút; phần benchmark dùng kết quả đã lưu nếu thời gian bảo vệ không đủ để chờ mọi vòng đo."
], table=(["Nhóm tệp", "Mục đích", "Chứa khóa bí mật?"], [["Mã nguồn và tests", "Chạy và kiểm chứng", "Không"], ["samples", "Xác minh độc lập", "Không"], ["reference_run", "CSV và môi trường đo", "Không"], ["report", "Word và PDF", "Không"]]))

